/// <reference types="vite/client" />
import type { EnemyId } from "../core/types";
import { ART_BOUNDS } from "./enemy-art-bounds";
/**
 * Visible part of an art file (alpha > 16) as a share of its square canvas: width `w` and height `h`, and the
 * centre of those bounds (`x`, `y`, from the canvas middle, +x right, +y down). Measured from the PNGs
 * (`ART_BOUNDS`, generated by `scripts/audit-enemy-art.ts`).
 */
export interface ArtBounds {
  w: number;
  h: number;
  x: number;
  y: number;
}
/** Painted body art for an enemy type; types without an entry keep their procedural body. */
export interface EnemyArt {
  /** Phaser texture key, unique per artwork. */
  texture: string;
  /** File under `public/`, without the base path. */
  path: string;
  /**
   * Longest visible side of the art as a multiple of the body diameter (`2 × r`); default `ART_SCALE`, slender art
   * a little more (`artScale`). It counts the drawn pixels, not the transparent canvas around them.
   */
  scale?: number;
  /** Radians added to the heading if the art does not face right. */
  angleOffset?: number;
  /**
   * Body radii the art sits behind the enemy's position, along its heading. Worms: the art shows the whole chain,
   * while the procedural head leads at the position and its segments trail behind.
   */
  shift?: number;
  /**
   * How the art follows the heading. Absent: top-down art, turned with the heading. `"profile"`: a side view of a
   * long body (vehicles, worms), turned with the heading but mirrored instead of upside down while it moves left.
   * `"upright"`: a side or front view standing on its feet, never turned, mirrored to face left or right.
   */
  pose?: "profile" | "upright";
  /** Measured visible bounds; without them the art is taken to fill `ART_FILL` of its canvas, centred. */
  bounds?: ArtBounds;
}
type Tuning = Pick<EnemyArt, "scale" | "angleOffset" | "shift" | "pose">;
/** Side and front views drawn standing (legs, tracks or tentacles at the bottom): a turned one would lie on its side. */
const UPRIGHT = { pose: "upright" } as const;
/** Long side views that follow the path: turned, but never upside down. */
const PROFILE = { pose: "profile" } as const;
/**
 * Default longest visible side in body diameters: as long as the procedural body's ground shadow (2.3 r) minus
 * its soft rim, so the art covers the body and the hit ring without reaching into the neighbouring units.
 */
export const ART_SCALE = 1.1;
/** Slender art (shorter side under `SLENDER_ASPECT` of the longer one) is shown `SLENDER_BOOST` longer, so it keeps some body. */
export const SLENDER_ASPECT = 0.6;
export const SLENDER_BOOST = 1.08;
/** Assumed visible share of a canvas without measured bounds. */
export const ART_FILL = 0.85;
/**
 * Every enemy with art in `public/assets/enemies/<id>.png`; all art faces right (heading 0). Poses come from the
 * contact sheet of the art: about half of it is drawn from the side, standing. Adding art for another
 * type is one entry here plus its PNG (then `scripts/audit-enemy-art.ts -- --write` for its bounds). Tuning comes
 * from the art review (`/gallery.html?art`, `scripts/enemy-art-review.ts`).
 */
const PAINTED = {
  aegis: {},
  airship: PROFILE,
  // The smallest body (0.15) on thin art: 1.3 diameters keep its legs readable in a swarm without merging ants.
  ant: { scale: 1.3 },
  ashwing: {},
  berserker: UPRIGHT,
  blinker: {},
  // The Titan leads the hierarchy: 8% over the default, so it reads as the largest unit (monolith, colossus and
  // broodmother are within 0.04 of its body size) while its HP bar still clears the art at every heading.
  boss: { scale: 1.2 },
  broodmother: UPRIGHT,
  bulwark: UPRIGHT,
  bunker: UPRIGHT,
  buoy: {},
  burrower: PROFILE,
  chainling: UPRIGHT,
  cinderwing: {},
  cog: {},
  colossus: UPRIGHT,
  crab: {},
  decoy: {},
  drafter: UPRIGHT,
  drone: {},
  // A thin running side view (a third of its length high): longer, so it keeps some body.
  ember: { ...UPRIGHT, scale: 1.3 },
  flare: UPRIGHT,
  gale: PROFILE,
  gapper: UPRIGHT,
  // Old canvas scale 1.4 × its 0.84 visible length.
  glider: { scale: 1.18 },
  golem: UPRIGHT,
  hauler: PROFILE,
  hopper: UPRIGHT,
  hydra: {},
  hydraling: UPRIGHT,
  insulator: UPRIGHT,
  jelly: UPRIGHT,
  // Spindly legs around a small body (16% of its canvas drawn): larger, so the spider is not lost on the path.
  leaper: { ...UPRIGHT, scale: 1.25 },
  martyr: {},
  mender: UPRIGHT,
  mirrorwing: {},
  // Worms: art length matches the procedural chain (head at the position, segments trailing): 4.4 r for four
  // segments, 3.5 r for three, 5.4 r for five, of which the art shows its visible length.
  mole: { scale: 2.08, shift: 1.2, pose: "profile" },
  molter: UPRIGHT,
  // An obelisk standing upright in its art: turned so its tip leads.
  monolith: { angleOffset: Math.PI / 2 },
  moth: {},
  nautilus: UPRIGHT,
  nullbearer: UPRIGHT,
  pebble: UPRIGHT,
  phantom: {},
  phasewing: {},
  piston: PROFILE,
  prism: {},
  raptor: {},
  // A slim side view: shown a little larger so the tiny runner stays readable.
  runner: { scale: 1.32 },
  salamander: { scale: 1.66, shift: 0.75, pose: "profile" },
  sapper: UPRIGHT,
  scarab: {},
  shade: UPRIGHT,
  skater: UPRIGHT,
  skimmer: {},
  slime: UPRIGHT,
  soulspark: {},
  sparkworm: { scale: 2.44, shift: 1.6, pose: "profile" },
  splitter: {},
  staticloud: {},
  stormbird: {},
  stormcell: {},
  tank: { scale: 1.23 },
  thornback: UPRIGHT,
  tidewing: {},
  twin: {},
  veiler: UPRIGHT,
  warden: UPRIGHT,
  warlord: UPRIGHT,
  warpdrone: {},
  wisp: {},
  wolf: UPRIGHT,
} satisfies Partial<Record<EnemyId, Tuning>>;
export const ENEMY_ART: Readonly<Partial<Record<EnemyId, EnemyArt>>> = Object.fromEntries(
  Object.entries(PAINTED).map(([id, tuning]) => [id, { texture: `enemy:${id}`, path: `assets/enemies/${id}.png`, ...tuning, bounds: ART_BOUNDS[id as EnemyId] }]),
);
/** Longest visible side in body diameters: the explicit `scale`, or `ART_SCALE` (slender art a little more). */
export function artScale(art: EnemyArt) {
  if (art.scale !== undefined) return art.scale;
  const b = art.bounds;
  return b && Math.min(b.w, b.h) < SLENDER_ASPECT * Math.max(b.w, b.h) ? ART_SCALE * SLENDER_BOOST : ART_SCALE;
}
/**
 * Displayed square edge of the art's canvas as a multiple of the body diameter: the canvas is larger than the
 * art by the transparent margin, so the visible longest side comes out at `artScale`.
 */
export function artEdge(art: EnemyArt) {
  const b = art.bounds;
  return artScale(art) / (b ? Math.max(b.w, b.h) : ART_FILL);
}
/** The art of an enemy type, or undefined for a procedural one. */
export const artFor = (type: EnemyId): EnemyArt | undefined => ENEMY_ART[type];
/** URL of an art file below the configured Vite base path (`/` in dev, `base` of the build). */
export const artUrl = (art: EnemyArt, base: string = import.meta.env.BASE_URL) => `${base.endsWith("/") ? base : `${base}/`}${art.path}`;
